/* Cover animation: a vector brain slice (contours of a maze-like field) that dissolves into the GenoBit helix.
   Reused from the GenoBit Biomarkers deck. Expects #brainG and #helix inside the cover SVG. */
  (function(){
    var NS='http://www.w3.org/2000/svg',t,x,i;
    var FD="";
    function buildBrain(){
      var W=480,H=270,raw=atob(FD),f=new Float32Array(W*H),k,cx=960,cy=540,RX=770,RY=420;
      for(k=0;k<raw.length;k++){var c=raw.charCodeAt(k);f[2*k]=(c>>4)/15;f[2*k+1]=(c&15)/15;}
      var g=new Float32Array(W*H),xx,yy,dx,dy;
      for(yy=0;yy<H;yy++)for(xx=0;xx<W;xx++){var sm=0;for(dy=-1;dy<=1;dy++)for(dx=-1;dx<=1;dx++)sm+=f[((yy+dy+H)%H)*W+(xx+dx+W)%W];g[yy*W+xx]=sm/9;}
      var sorted=Array.prototype.slice.call(g).sort(function(a,b){return a-b;}),th=sorted[Math.floor(sorted.length*.55)];
      function rrAt(x,y){var u=(x-cx)/RX,v=(y-cy)/RY,uu=u*(1-.2*v),a=Math.atan2(v,uu);return Math.sqrt(uu*uu+v*v)*(1-.018*Math.sin(5*a+1)-.014*Math.sin(9*a)-.008*Math.sin(13*a+2));}
      function dOut(x,y){return(1-rrAt(x,y))*440;}
      function dAll(x,y){return Math.min(dOut(x,y),Math.abs(y-cy)-9);}
      function clearV(x,y){return Math.sqrt(Math.pow((x-cx)/470,2)+Math.pow((y-cy)/190,2));}
      var DO=new Float32Array(W*H),DA=new Float32Array(W*H);
      for(yy=0;yy<H;yy++)for(xx=0;xx<W;xx++){DO[yy*W+xx]=dOut(xx*4,yy*4);DA[yy*W+xx]=dAll(xx*4,yy*4);}
      function contour(val,thr,keep){
        var segs=[],adj={},j,i2;
        function add(id,si){(adj[id]||(adj[id]=[])).push(si);}
        function P(id,va,vb){var e=id&1,cell=id>>1,ci=cell%W,cj=(cell-ci)/W,tt=(thr-va)/(vb-va);return e===0?[(ci+tt)*4,cj*4]:[ci*4,(cj+tt)*4];}
        for(j=0;j<H-1;j++)for(i2=0;i2<W-1;i2++){
          var a0=val[j*W+i2],b0=val[j*W+i2+1],c0=val[(j+1)*W+i2+1],d0=val[(j+1)*W+i2];
          var m=(a0>thr?1:0)|(b0>thr?2:0)|(c0>thr?4:0)|(d0>thr?8:0);if(m===0||m===15)continue;
          var T=(j*W+i2)*2,Bt=((j+1)*W+i2)*2,L=(j*W+i2)*2+1,R=(j*W+i2+1)*2+1,pr=[];
          switch(m){case 1:case 14:pr=[[L,T]];break;case 2:case 13:pr=[[T,R]];break;case 3:case 12:pr=[[L,R]];break;case 4:case 11:pr=[[R,Bt]];break;case 5:pr=[[L,T],[R,Bt]];break;case 6:case 9:pr=[[T,Bt]];break;case 7:case 8:pr=[[L,Bt]];break;case 10:pr=[[T,R],[L,Bt]];break;}
          pr.forEach(function(q){
            function val2(id){var e=id&1,cell=id>>1;return e===0?[val[cell],val[cell+1]]:[val[cell],val[cell+W]];}
            var v1=val2(q[0]),v2=val2(q[1]),p1=P(q[0],v1[0],v1[1]),p2=P(q[1],v2[0],v2[1]);
            if(keep((p1[0]+p2[0])/2,(p1[1]+p2[1])/2)){var si=segs.length;segs.push({a:q[0],b:q[1],pa:p1,pb:p2,u:false});add(q[0],si);add(q[1],si);}
          });
        }
        var out=[];
        function other(id,si){var l=adj[id]||[],z;for(z=0;z<l.length;z++)if(l[z]!==si&&!segs[l[z]].u)return l[z];return -1;}
        segs.forEach(function(sg,si){
          if(sg.u)return;sg.u=true;var pts=[sg.pa,sg.pb],endId=sg.b,cur=si,n;
          while((n=other(endId,cur))>=0){var s2=segs[n];s2.u=true;if(s2.a===endId){pts.push(s2.pb);endId=s2.b;}else{pts.push(s2.pa);endId=s2.a;}cur=n;}
          endId=sg.a;cur=si;
          while((n=other(endId,cur))>=0){var s3=segs[n];s3.u=true;if(s3.a===endId){pts.unshift(s3.pb);endId=s3.b;}else{pts.unshift(s3.pa);endId=s3.a;}cur=n;}
          out.push(pts);
        });
        return out;
      }
      function toD(pts){
        var q=[pts[0]],z;for(z=2;z<pts.length-1;z+=2)q.push(pts[z]);q.push(pts[pts.length-1]);
        if(q.length<3)return 'M'+q[0][0].toFixed(1)+' '+q[0][1].toFixed(1)+' L'+q[q.length-1][0].toFixed(1)+' '+q[q.length-1][1].toFixed(1);
        var d='M'+q[0][0].toFixed(1)+' '+q[0][1].toFixed(1),m;
        for(z=1;z<q.length-1;z++){m=[(q[z][0]+q[z+1][0])/2,(q[z][1]+q[z+1][1])/2];d+=' Q'+q[z][0].toFixed(1)+' '+q[z][1].toFixed(1)+' '+m[0].toFixed(1)+' '+m[1].toFixed(1);}
        return d+' L'+q[q.length-1][0].toFixed(1)+' '+q[q.length-1][1].toFixed(1);
      }
      var bg=document.getElementById('brainG');
      var seed=5;function rnd(){seed=(seed*16807)%2147483647;return seed/2147483647;}
      function group(en,ex,gd,ge){var e=document.createElementNS(NS,'g');e.setAttribute('class','bl');e.style.setProperty('--en',en);e.style.setProperty('--ex',ex);e.style.setProperty('--gd',gd+'s');e.style.setProperty('--ge',ge+'s');bg.appendChild(e);return e;}
      function line(gr,pts,col,w,op,d,de){var e=document.createElementNS(NS,'path');e.setAttribute('d',toD(pts));e.setAttribute('pathLength','1');e.setAttribute('stroke',col);e.setAttribute('stroke-width',w);if(op<1)e.setAttribute('opacity',op);e.style.setProperty('--d',d+'s');e.style.setProperty('--de',(de||0)+'s');gr.appendChild(e);}
      var gSk=group(1.25,1.5,.05,0),gCs=group(1.4,2,.35,.1),gOu=group(1.6,2.6,.7,.2),gL=group(2,3.4,.9,.3),gR=group(2,3.6,.9,.35);
      /* cráneo (hueso) */
      [-60,-70].forEach(function(lv,q){contour(DO,lv,function(){return true;}).forEach(function(p){if(p.length>12)line(gSk,p,'#B7C2CE',q?3:4.5,q?.55:.8,.1+q*.3);});});
      /* líquido que separa cráneo y cerebro */
      [-16,-34].forEach(function(lv,q){contour(DO,lv,function(){return true;}).forEach(function(p){if(p.length>12)line(gCs,p,q?'#5DB1F0':'#2E8FE0',q?4:5.5,1,.7+q*.3);});});
      /* contorno de hemisferios (cortado donde va el título) */
      contour(DA,0,function(x,y){return clearV(x,y)>1.0;}).forEach(function(p){if(p.length>6){var mx=0,z;for(z=0;z<p.length;z++)mx+=p[z][1];mx/=p.length;line(gOu,p,mx<cy?'#D3F6F3':'#DCDDFB',6,1,1.2);}});
      /* circunvoluciones */
      contour(g,th,function(x,y){return dAll(x,y)>16&&clearV(x,y)>1.07;}).forEach(function(p){
        if(p.length<10)return;var mx=0,my=0,z;for(z=0;z<p.length;z++){mx+=p[z][0];my+=p[z][1];}mx/=p.length;my/=p.length;
        var rr=rrAt(mx,my),left=my<cy,outer=rr>.78,col=left?(outer?'#2FD0C6':'#0E9D95'):(outer?'#B4B5F7':'#8486DD');
        line(left?gL:gR,p,col,outer?4.6:4,1,1.5+(1-rr)*2.2+rnd()*.5,rnd()*.5);
      });
    }
    setTimeout(buildBrain,20);
    /* hélice */
    var g2=document.getElementById('helix'),A='',B='';
    for(x=70;x<=630;x+=7){t=(x-70)/280*2*Math.PI;A+=(x===70?'M':'L')+x+' '+(345+62*Math.sin(t)).toFixed(1)+' ';B+=(x===70?'M':'L')+x+' '+(345-62*Math.sin(t)).toFixed(1)+' ';}
    function hx(c,dd,fx,fy,l){var e=document.createElementNS(NS,'path');e.setAttribute('d',dd);e.setAttribute('class','hx lp '+c);e.style.setProperty('--fx',fx);e.style.setProperty('--fy',fy);e.style.setProperty('--l',l);g2.appendChild(e);}
    hx('a',A,'-1700px','260px','.2s');hx('b',B,'1700px','-260px','.35s');
    for(x=84;x<=616;x+=28){t=(x-70)/280*2*Math.PI;var sn=Math.sin(t);if(Math.abs(sn)<.4)continue;var l=document.createElementNS(NS,'line');l.setAttribute('class','lr');l.setAttribute('x1',x);l.setAttribute('x2',x);l.setAttribute('y1',(345+62*sn*.82).toFixed(1));l.setAttribute('y2',(345-62*sn*.82).toFixed(1));l.style.transitionDelay=(2.1+x/700)+'s';g2.appendChild(l);}
  })();
